// en el celular el botón «+ Agregar paciente» quedaba oculto: botón flotante en Inicio
const rr0 = render;
render = function () {
  const r = rr0.apply(this, arguments);
  try {
    let b = document.getElementById('ar_fab');
    const ver = DB && (VISTA === 'panel' || VISTA === 'hoy' || VISTA === 'pacientes');
    if (ver && !b) { document.body.insertAdjacentHTML('beforeend', '<button id="ar_fab" onclick="agregarRapido(1)" aria-label="Agregar paciente">＋ Agregar paciente</button>'); }
    else if (!ver && b) b.remove();
  } catch (e) {}
  return r;
};
window.render = render;
